<?php
/**
 * Block editor script registration and enqueue.
 *
 * This file will be copied to the assets build directory.
 *
 * @package wp-curate
 */

namespace Alley\WP\WP_Curate;

/**
 * Registers block editor assets.
 */
function register_block_editor_scripts(): void {
	$supported_post_types = new Supported_Post_Types();

	if ( ! $supported_post_types->should_register_block() ) {
		return;
	}

	/**
	 * Asset file generated by wp-scripts.
	 *
	 * @var array{dependencies: non-empty-string[], version: string}|false $asset_file
	 */
	$asset_file = include __DIR__ . '/index.asset.php';

	$src = plugins_url( 'index.js', __FILE__ );

	if ( ! $asset_file || '' === $src ) {
		return;
	}

	wp_register_script(
		'wp-curate_block_editor',
		$src,
		$asset_file['dependencies'],
		$asset_file['version'],
		true
	);

	wp_set_script_translations( 'wp-curate_block_editor', 'wp-curate' );
}
add_action( 'init', __NAMESPACE__ . '\register_block_editor_scripts' );

/**
 * Enqueue block editor assets for this slotfill.
 */
function action_enqueue_block_editor_assets(): void {
	wp_enqueue_script( 'wp-curate_block_editor' );
}
add_action( 'enqueue_block_editor_assets', __NAMESPACE__ . '\action_enqueue_block_editor_assets' );
